export type TaskStatusType = "todo" | "in progress" | "done";

export class TaskStatus {
  constructor(private readonly value: TaskStatusType) {}

  static todo(): TaskStatus {
    return new TaskStatus("todo");
  }

  static inProgress(): TaskStatus {
    return new TaskStatus("in progress");
  }

  static done(): TaskStatus {
    return new TaskStatus("done");
  }

  static fromString(value: string): TaskStatus {
    if (!["todo", "in progress", "done"].includes(value)) {
      throw new Error(`Invalid task status: ${value}`);
    }
    return new TaskStatus(value as TaskStatusType);
  }

  getValue(): TaskStatusType {
    return this.value;
  }

  isDone(): boolean {
    return this.value === "done";
  }

  equals(other: TaskStatus): boolean {
    return this.value === other.value;
  }
}

